package com.rgapro1.ocaso;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.hardware.biometrics.BiometricPrompt;
import android.os.*;
import android.text.InputType;
import android.util.Base64;
import android.view.*;
import android.widget.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.*;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

public class MainActivity extends Activity {
    private static final int NAVY=Color.rgb(20,55,100), BLUE=Color.rgb(11,114,231), BG=Color.rgb(245,247,250), TEXT=Color.rgb(25,35,50), MUTED=Color.rgb(95,105,120);
    private static final int PBKDF2_ITERATIONS=120000;
    private static final String[] TYPES={"Todas","Decesos","Vida","Hogar","Auto","Salud","Accidentes","Otros"};
    private SharedPreferences prefs; private LinearLayout content; private String currentUser; private final Executor executor=Executors.newSingleThreadExecutor();
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);migrateLegacy();if(!hasPin())createFirstUser();else access();}
    private boolean hasPin(){return prefs.contains("pin_hash")&&prefs.contains("pin_salt");}
    private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);return e;}
    private EditText pin(String h){EditText e=input(h);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView label(String s,float z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setMinHeight(0);b.setTextColor(TEXT);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(12));g.setStroke(dp(1),Color.rgb(220,225,232));b.setBackground(g);return b;}
    private Button primary(String s){Button b=button(s);b.setTextColor(Color.WHITE);GradientDrawable g=new GradientDrawable();g.setColor(BLUE);g.setCornerRadius(dp(12));b.setBackground(g);return b;}
    private JSONObject users(){try{return new JSONObject(prefs.getString("users_json","{}"));}catch(Exception e){return new JSONObject();}}
    private void saveUsers(JSONObject u){prefs.edit().putString("users_json",u.toString()).apply();}
    private void migrateLegacy(){try{JSONObject u=users();if(u.length()==0&&prefs.getStringSet("policies",null)!=null){JSONObject admin=new JSONObject();admin.put("pin_hash",prefs.getString("pin_hash",""));admin.put("pin_salt",prefs.getString("pin_salt",""));JSONArray p=new JSONArray();for(String s:prefs.getStringSet("policies",new HashSet<>()))p.put(s);admin.put("policies",p);u.put("Administrador",admin);saveUsers(u);prefs.edit().remove("policies").apply();}else if(u.length()==0&&hasPin()){JSONObject admin=new JSONObject();admin.put("pin_hash",prefs.getString("pin_hash",""));admin.put("pin_salt",prefs.getString("pin_salt",""));admin.put("policies",new JSONArray());u.put("Administrador",admin);saveUsers(u);}}catch(Exception ignored){}}
    private void createFirstUser(){final EditText name=input("Nombre de usuario"),a=pin("Clave de 6 dígitos"),b=pin("Repite la clave");LinearLayout box=vertical();box.setPadding(dp(18),0,dp(18),0);box.addView(name);box.addView(a);box.addView(b);AlertDialog d=new AlertDialog.Builder(this).setTitle("Configura tu usuario").setMessage("Cada usuario tendrá su propia cartera. Los datos no se comparten entre usuarios.").setView(box).setCancelable(false).setPositiveButton("Crear",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim(),p=a.getText().toString();if(n.isEmpty()){name.setError("Indica un nombre");return;}if(!p.matches("\\d{6}")||!p.equals(b.getText().toString())){b.setError("La clave debe ser de 6 dígitos y coincidir");return;}try{JSONObject u=users(),o=new JSONObject();byte[] s=new byte[16];new SecureRandom().nextBytes(s);o.put("pin_hash",Base64.encodeToString(derive(p,s),Base64.NO_WRAP));o.put("pin_salt",Base64.encodeToString(s,Base64.NO_WRAP));o.put("policies",new JSONArray());u.put(n,o);saveUsers(u);prefs.edit().putString("pin_hash",o.getString("pin_hash")).putString("pin_salt",o.getString("pin_salt")).apply();currentUser=n;d.dismiss();home();}catch(Exception e){Toast.makeText(this,"No se pudo crear el usuario",Toast.LENGTH_LONG).show();}}));d.show();}
    private byte[] derive(String p,byte[] s)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),s,PBKDF2_ITERATIONS,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
    private boolean verifyUser(String n,String p){try{JSONObject o=users().optJSONObject(n);if(o==null)return false;return MessageDigest.isEqual(Base64.decode(o.optString("pin_hash"),0),derive(p,Base64.decode(o.optString("pin_salt"),0)));}catch(Exception e){return false;}}
    private JSONArray policies(){try{JSONObject o=users().optJSONObject(currentUser);return o==null?new JSONArray():o.optJSONArray("policies");}catch(Exception e){return new JSONArray();}}
    private void savePolicies(JSONArray a){try{JSONObject u=users(),o=u.getJSONObject(currentUser);o.put("policies",a);u.put(currentUser,o);saveUsers(u);}catch(Exception ignored){}}
    private void access(){LinearLayout r=vertical();r.setGravity(Gravity.CENTER);r.setPadding(dp(28),dp(24),dp(28),dp(24));r.setBackgroundColor(BG);TextView t=label("RgaPro",30,NAVY,true);t.setGravity(Gravity.CENTER);r.addView(t,new LinearLayout.LayoutParams(-1,dp(60)));TextView s=label("Selecciona usuario y desbloquea tu cartera",16,MUTED,false);s.setGravity(Gravity.CENTER);r.addView(s,new LinearLayout.LayoutParams(-1,dp(44)));Spinner us=new Spinner(this);ArrayList<String> names=new ArrayList<>();Iterator<String> it=users().keys();while(it.hasNext())names.add(it.next());Collections.sort(names);us.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));r.addView(us,new LinearLayout.LayoutParams(-1,dp(54)));Button p=primary("Entrar con clave");p.setOnClickListener(v->login(String.valueOf(us.getSelectedItem())));r.addView(p,new LinearLayout.LayoutParams(-1,dp(54)));if(Build.VERSION.SDK_INT>=28){Button bio=button("Usar biometría");bio.setOnClickListener(v->{currentUser=String.valueOf(us.getSelectedItem());biometric();});LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(54));bp.topMargin=dp(10);r.addView(bio,bp);}r.addView(label("Datos separados por usuario · compartir solo bajo confirmación",12,MUTED,false),new LinearLayout.LayoutParams(-1,dp(50)));setContentView(r);}
    private void login(String user){EditText e=pin("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("Desbloquear "+user).setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(verifyUser(user,e.getText().toString())){currentUser=user;d.dismiss();home();}else e.setError("Clave incorrecta");}));d.show();}
    private void biometric(){if(Build.VERSION.SDK_INT<28){login(currentUser);return;}BiometricPrompt p=new BiometricPrompt.Builder(this).setTitle("Acceso a RgaPro").setSubtitle(currentUser).setDescription("Confirma tu identidad con la biometría del dispositivo.").setNegativeButton("Usar clave",executor,(d,w)->runOnUiThread(()->login(currentUser))).build();p.authenticate(null,executor,new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(MainActivity.this::home);}public void onAuthenticationError(int c,CharSequence m){runOnUiThread(()->Toast.makeText(MainActivity.this,"Biometría: "+m,Toast.LENGTH_SHORT).show());}});}
    private void header(LinearLayout root,String title){LinearLayout h=new LinearLayout(this);h.setGravity(Gravity.CENTER_VERTICAL);h.setPadding(dp(10),0,dp(16),0);h.setBackgroundColor(NAVY);Button back=button("‹");back.setTextColor(Color.WHITE);back.setTextSize(30);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->home());h.addView(back,new LinearLayout.LayoutParams(dp(48),dp(64)));h.addView(label(title,21,Color.WHITE,true),new LinearLayout.LayoutParams(0,dp(64),1));root.addView(h);}
    private void page(String title,String sub){LinearLayout root=vertical();root.setBackgroundColor(BG);header(root,title);content=vertical();content.setPadding(dp(18),dp(16),dp(18),dp(30));if(sub!=null)content.addView(label(sub,14,MUTED,false),new LinearLayout.LayoutParams(-1,dp(50)));ScrollView sc=new ScrollView(this);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void home(){LinearLayout root=vertical();root.setBackgroundColor(BG);TextView top=label("RgaPro  ·  "+currentUser,22,Color.WHITE,true);top.setPadding(dp(18),0,dp(18),0);top.setBackgroundColor(NAVY);root.addView(top,new LinearLayout.LayoutParams(-1,dp(68)));ScrollView sc=new ScrollView(this);LinearLayout body=vertical();body.setPadding(dp(20),dp(20),dp(20),dp(28));addHome(body,"CLIENTES","Buscar por cualquier dato",v->clients());addHome(body,"PÓLIZAS","Separadas por tipo",v->policiesPage());addHome(body,"VENCIMIENTOS","Próximas caducidades",v->expiries());addHome(body,"SEGURIDAD Y USUARIOS","Gestionar usuarios y acceso",v->settings());addHome(body,"COMPARTIR","Solo cuando tú lo autorices",v->shareHelp());Button lock=button("Cerrar sesión");lock.setOnClickListener(v->{currentUser=null;access();});body.addView(lock,new LinearLayout.LayoutParams(-1,dp(52)));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void addHome(LinearLayout p,String a,String b,View.OnClickListener l){LinearLayout c=vertical();c.setPadding(dp(18),dp(8),dp(18),dp(8));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(14));g.setStroke(dp(1),Color.rgb(225,229,235));c.setBackground(g);c.setOnClickListener(l);c.addView(label(a,17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(28)));c.addView(label(b,13,MUTED,false),new LinearLayout.LayoutParams(-1,dp(24)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(70));cp.topMargin=dp(11);p.addView(c,cp);}
    private void clients(){page("Clientes","Los resultados pertenecen exclusivamente a: "+currentUser);EditText q=input("Buscar nombre, DNI, teléfono, póliza o cualquier dato");content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));Button add=primary("+ Nueva póliza");add.setOnClickListener(v->addPolicy(null));content.addView(add,new LinearLayout.LayoutParams(-1,dp(50)));LinearLayout list=vertical();content.addView(list);Runnable render=()->{list.removeAllViews();JSONArray a=policies();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,q.getText().toString(),"Todas")){LinearLayout rr=row(p.optString("holder"),p.optString("type")+" · "+p.optString("number"));rr.setOnClickListener(v->detail(p));list.addView(rr);}}};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
    private boolean match(JSONObject p,String q,String type){if(!type.equals("Todas")&&!type.equals(p.optString("type")))return false;String n=norm(q);if(n.isEmpty())return true;for(String k:new String[]{"type","number","expiry","holder","holderDni","phone","email","address"})if(norm(p.optString(k)).contains(n))return true;JSONArray m=p.optJSONArray("members");if(m!=null)for(int i=0;i<m.length();i++)if(norm(m.optString(i)).contains(n))return true;return false;}
    private String norm(String s){return java.text.Normalizer.normalize(s==null?"":s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);}
    private LinearLayout row(String a,String b){LinearLayout r=vertical();r.setPadding(dp(16),dp(7),dp(16),dp(7));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(12));g.setStroke(dp(1),Color.rgb(225,229,235));r.setBackground(g);r.addView(label(a,16,TEXT,true),new LinearLayout.LayoutParams(-1,dp(30)));r.addView(label(b,13,MUTED,false),new LinearLayout.LayoutParams(-1,dp(24)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(64));rp.topMargin=dp(9);r.setLayoutParams(rp);return r;}
    private void detail(JSONObject p){String msg="Titular: "+p.optString("holder")+"\nDNI/NIF: "+p.optString("holderDni")+"\nTeléfono: "+p.optString("phone")+"\nEmail: "+p.optString("email")+"\nDirección: "+p.optString("address")+"\nTipo: "+p.optString("type")+"\nPóliza: "+p.optString("number")+"\nVencimiento: "+p.optString("expiry");JSONArray m=p.optJSONArray("members");if(m!=null)for(int i=0;i<m.length();i++){JSONObject x=m.optJSONObject(i);msg+="\n• "+(x==null?m.optString(i):x.optString("name")+" · "+x.optString("dni")+" · "+x.optString("relation"));}new AlertDialog.Builder(this).setTitle("Ficha de póliza").setMessage(msg).setPositiveButton("Cerrar",null).setNegativeButton("Editar",(d,w)->addPolicy(p)).setNeutralButton("Compartir",(d,w)->confirmShare(p,msg)).show();}
    private void confirmShare(JSONObject p,String msg){new AlertDialog.Builder(this).setTitle("Compartir datos").setMessage("No se comparte nada automáticamente. Si continúas, se abrirá el selector de Android y tú elegirás la aplicación y el destinatario. Revisa los datos antes de enviarlos.").setNegativeButton("Cancelar",null).setPositiveButton("Sí, quiero compartir",(d,w)->shareText("RgaPro · "+p.optString("holder"),msg));}
    private void shareText(String title,String text){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Compartir datos seleccionados"));}
    private void shareHelp(){new AlertDialog.Builder(this).setTitle("Privacidad de los datos").setMessage("RgaPro no envía ni comparte la cartera por su cuenta. Cada usuario tiene una cartera independiente. La opción Compartir solo aparece en la ficha de una póliza y requiere una confirmación explícita antes de abrir el selector de Android.").setPositiveButton("Entendido",null).show();}
    private void addPolicy(JSONObject old){LinearLayout box=vertical();box.setPadding(dp(18),0,dp(18),0);EditText holder=input("Titular"),dni=input("DNI / NIF"),phone=input("Teléfono"),email=input("Email"),address=input("Dirección"),number=input("Número de póliza"),expiry=input("Vencimiento AAAA-MM-DD");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,Arrays.copyOfRange(TYPES,1,TYPES.length)));for(EditText e:new EditText[]{holder,dni,phone,email,address,number,expiry})box.addView(e,new LinearLayout.LayoutParams(-1,dp(50)));box.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout members=vertical();box.addView(label("En Decesos: personas aseguradas",14,MUTED,true));box.addView(members);List<EditText[]> fields=new ArrayList<>();Button add=button("+ Añadir persona");add.setOnClickListener(v->{EditText n=input("Nombre y apellidos"),dn=input("DNI/NIE"),dob=input("Fecha nacimiento"),rel=input("Parentesco"),ph=input("Teléfono"),ad=input("Domicilio");EditText[] fs={n,dn,dob,rel,ph,ad};fields.add(fs);for(EditText e:fs)members.addView(e,new LinearLayout.LayoutParams(-1,dp(46)));});box.addView(add,new LinearLayout.LayoutParams(-1,dp(48)));if(old!=null){holder.setText(old.optString("holder"));dni.setText(old.optString("holderDni"));phone.setText(old.optString("phone"));email.setText(old.optString("email"));address.setText(old.optString("address"));number.setText(old.optString("number"));expiry.setText(old.optString("expiry"));String typ=old.optString("type");int pos=Arrays.asList(Arrays.copyOfRange(TYPES,1,TYPES.length)).indexOf(typ);if(pos>=0)type.setSelection(pos);}AlertDialog d=new AlertDialog.Builder(this).setTitle(old==null?"Nueva póliza":"Editar póliza").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{JSONObject p=old==null?new JSONObject():new JSONObject(old.toString());p.put("id",old==null?UUID.randomUUID().toString():old.optString("id"));p.put("holder",holder.getText().toString());p.put("holderDni",dni.getText().toString());p.put("phone",phone.getText().toString());p.put("email",email.getText().toString());p.put("address",address.getText().toString());p.put("number",number.getText().toString());p.put("expiry",expiry.getText().toString());p.put("type",String.valueOf(type.getSelectedItem()));JSONArray mem=new JSONArray();for(EditText[] fs:fields){JSONObject person=new JSONObject();person.put("name",fs[0].getText().toString());person.put("dni",fs[1].getText().toString());person.put("birth",fs[2].getText().toString());person.put("relation",fs[3].getText().toString());person.put("phone",fs[4].getText().toString());person.put("address",fs[5].getText().toString());mem.put(person);}if(old!=null&&mem.length()==0&&old.optJSONArray("members")!=null)mem=old.optJSONArray("members");p.put("members",mem);JSONArray a=policies();if(old!=null){for(int i=0;i<a.length();i++){JSONObject z=a.optJSONObject(i);if(z!=null&&z.optString("id").equals(p.optString("id"))){a.put(i,p);break;}}}else a.put(p);savePolicies(a);d.dismiss();clients();}catch(Exception e){Toast.makeText(this,"No se pudo guardar",Toast.LENGTH_LONG).show();}}));d.show();}
    private void policiesPage(){page("Pólizas","Cada usuario ve únicamente su propia cartera.");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,TYPES));content.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout list=vertical();content.addView(list);Runnable r=()->{list.removeAllViews();JSONArray a=policies();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,"",String.valueOf(type.getSelectedItem()))){LinearLayout rr=row(p.optString("holder"),p.optString("type")+" · vence "+p.optString("expiry"));rr.setOnClickListener(v->detail(p));list.addView(rr);}}};type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){r.run();}});r.run();}
    private void expiries(){page("Vencimientos","Próximas caducidades de "+currentUser);ArrayList<JSONObject> list=new ArrayList<>();JSONArray a=policies();long now=System.currentTimeMillis();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p==null)continue;try{Date d=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(p.optString("expiry"));if(d!=null&&d.getTime()>=now&&d.getTime()<=now+30L*24*60*60*1000)list.add(p);}catch(Exception ignored){}}if(list.isEmpty())content.addView(label("No hay pólizas que caduquen en los próximos 30 días.",15,MUTED,false));for(JSONObject p:list){LinearLayout rr=row(p.optString("holder"),p.optString("type")+" · "+p.optString("expiry"));rr.setOnClickListener(v->detail(p));content.addView(rr);}}
    private void settings(){page("Seguridad y usuarios","Los usuarios y sus carteras están separados.");content.addView(label("Usuario activo: "+currentUser,17,TEXT,true));Button add=primary("+ Añadir usuario");add.setOnClickListener(v->createAdditionalUser());content.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));Button sw=button("Cambiar de usuario");sw.setOnClickListener(v->{currentUser=null;access();});content.addView(sw,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(label("Compartición: DESACTIVADA por defecto. Solo se inicia desde la ficha de una póliza y requiere confirmación.",14,MUTED,false));}
    private void createAdditionalUser(){final EditText name=input("Nombre de usuario"),a=pin("Clave de 6 dígitos"),b=pin("Repite la clave");LinearLayout box=vertical();box.setPadding(dp(18),0,dp(18),0);box.addView(name);box.addView(a);box.addView(b);new AlertDialog.Builder(this).setTitle("Nuevo usuario").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Crear",(d,w)->{String n=name.getText().toString().trim(),p=a.getText().toString();if(n.isEmpty()||!p.matches("\\d{6}")||!p.equals(b.getText().toString())){Toast.makeText(this,"Nombre y clave de 6 dígitos obligatorios",Toast.LENGTH_LONG).show();return;}try{JSONObject u=users();if(u.has(n)){Toast.makeText(this,"Ese usuario ya existe",Toast.LENGTH_SHORT).show();return;}JSONObject o=new JSONObject();byte[] s=new byte[16];new SecureRandom().nextBytes(s);o.put("pin_hash",Base64.encodeToString(derive(p,s),Base64.NO_WRAP));o.put("pin_salt",Base64.encodeToString(s,Base64.NO_WRAP));o.put("policies",new JSONArray());u.put(n,o);saveUsers(u);Toast.makeText(this,"Usuario creado con cartera independiente",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"No se pudo crear",Toast.LENGTH_LONG).show();}}).show();}
}
